package com.aoo.bcg.share;
import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Clock;import java.util.HexFormat;
public final class InviteAccountAuthenticator{private final byte[] secret;private final Clock clock;public InviteAccountAuthenticator(String s,Clock c){if(s==null||s.length()<32)throw new IllegalArgumentException("auth secret must be at least 32 characters");secret=s.getBytes(StandardCharsets.UTF_8);clock=c;}public long authenticate(String h){try{if(h==null||!h.startsWith("Bearer "))throw rejected();String[]p=h.substring(7).split("\\.",-1);if(p.length!=3)throw rejected();long a=Long.parseLong(p[0]),x=Long.parseLong(p[1]);if(a<=0||x<clock.instant().getEpochSecond()||x>clock.instant().plusSeconds(300).getEpochSecond())throw rejected();Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret,"HmacSHA256"));if(!MessageDigest.isEqual(m.doFinal((p[0]+"."+p[1]).getBytes(StandardCharsets.UTF_8)),HexFormat.of().parseHex(p[2])))throw rejected();return a;}catch(InviteLinkError e){throw e;}catch(Exception e){throw rejected();}}private static InviteLinkError rejected(){return new InviteLinkError(401,"INVITE_UNAUTHORIZED","valid account bearer assertion required");}}
